from itertools import product
from math import exp
p={}
for h,v,c,r,y in product((0,1), repeat=5):
    phv=(1/6 if h==v else 1/3)
    pr=1/(1+exp(-(0.75*h+0.5*c)))
    py=1/(1+exp(-(-0.5+2.5*v+1.75*c)))
    p[h,v,c,r,y]=phv*0.5*(pr if r else 1-pr)*(py if y else 1-py)
def y_prob(**cond):
    indices={'h':0,'v':1,'c':2,'r':3}
    rows=[(k,q) for k,q in p.items() if all(k[indices[n]]==x for n,x in cond.items())]
    return sum(q for k,q in rows if k[4]==1)/sum(q for k,q in rows)
for h in (0,1):
    print('P(Y=1 | H='+str(h)+') =', y_prob(h=h))
for c,r in product((0,1),repeat=2):
    print('P(Y=1 | C='+str(c)+', R='+str(r)+') =', y_prob(c=c,r=r))
